const normalizeHeaders = (headers = {}) => {
  const entries = Object.entries(headers || {});
  return Object.fromEntries(
    entries.map(([key, value]) => [String(key || '').toLowerCase(), value])
  );
};

return items.map((item) => {
  const root = item.json || {};
  const body = root.body && typeof root.body === 'object' ? root.body : root;
  const headers = normalizeHeaders(root.headers || {});

  const message = body.message || body.question || '';
  const sessionId = body.session_id || body.sessionId || `sess_${Date.now()}`;
  const context = body.context || {};
  const history = body.history || [];

  return {
    json: {
      message,
      sessionId,
      context,
      history,
      source: context.source || 'unknown',
      language: context.language || 'auto',
      headers
    }
  };
});

return items.map((item) => {
  const response = item.json || {};

  return {
    json: {
      success: true,
      response: response.response || response.answer || response.message || 'No response',
      session_id: response.session_id || response.sessionId,
      timestamp: new Date().toISOString(),
      model_used: response.meta?.model || response.model || 'hermes',
      latency_ms: response.meta?.latencyMs || 0
    }
  };
});
